/* Momentum Radar: a dark trading-terminal theme. Green is momentum, amber is hot, red is cold. */
:root {
  --bg: #070b12;
  --panel: #0e1622;
  --panel2: #132030;
  --line: #1d2c40;
  --text: #e6f0f2;
  --muted: #7d8ea3;
  --accent: #00e676;
  --hot: #ffcf3f;
  --down: #ff5c5c;
  --row: #0a111c;
  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.wrap { max-width: 1240px; margin: 0 auto; padding: 0 20px; }
