.mover-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; }
.mover {
  background: var(--panel); border: 1px solid var(--line); border-left: 3px solid var(--accent);
  border-radius: 10px; padding: 12px 14px; cursor: pointer;
}
