td.name small { display: block; color: var(--muted); font-weight: 400; font-size: 12px; font-family: var(--mono); }
.up { color: var(--accent); }
.down { color: var(--down); }
.tag { display: inline-block; background: var(--accent); color: #04140a; font-size: 11px; font-weight: 700; border-radius: 20px; padding: 1px 8px; margin-left: 6px; vertical-align: 2px; }
.hottag { display: inline-block; background: var(--hot); color: #241a00; font-size: 11px; font-weight: 700; border-radius: 20px; padding: 1px 8px; margin-left: 6px; vertical-align: 2px; }
