.detail-head { display: flex; justify-content: space-between; gap: 16px; align-items: start; flex-wrap: wrap; }
.detail-head h2 { margin: 0 0 4px; font-size: 24px; }
.big { font-size: 26px; font-weight: 750; color: var(--accent); margin: 0; white-space: nowrap; font-family: var(--mono); }
table.model td:first-child { color: var(--muted); width: 46%; white-space: normal; }
table.model td:last-child { text-align: right; font-variant-numeric: tabular-nums; font-family: var(--mono); }
ol.steps { margin: 0; padding-left: 22px; }
ol.steps li { margin: 0 0 10px; padding-left: 4px; }
ol.steps li::marker { color: var(--accent); font-weight: 700; }
footer { padding: 8px 20px 30px; font-size: 13px; }
@media (max-width: 900px) {
  .mover-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  h1 { font-size: 23px; }
  .big { font-size: 21px; }
  .mover-grid { grid-template-columns: 1fr; }
  th:nth-child(3), td:nth-child(3) { display: none; }
}
